def get(self, key, default=None):
    p = self._path(key)
    if not os.path.exists(p):
        return default
    with open(p) as f:
        rec = json.load(f)
    if self._now() - rec.get("t", 0) > self.ttl:
        try:
            os.remove(p)
        except OSError:
            pass
        return default
    return rec["v"]
